"use client";

import { useState, useEffect, useCallback, useRef } from "react";

interface GameData {
  status: string;
  currentQuestion: {
    id: number;
    type: string;
    difficulty: string;
    question: string;
    options: string[];
    timeLimit: number;
  } | null;
  currentQuestionIndex: number;
  totalQuestions: number;
  timeRemaining: number;
  leaderboard: {
    rank: number;
    username: string;
    displayName: string;
    points: number;
    streak: number;
    team: string | null;
    title: string;
  }[];
  correctAnswer: string | null;
  winner: string | null;
  winnerDisplayName: string | null;
  bossRound: boolean;
  questionsAsked: number;
  totalPlayers: number;
  stats: {
    totalPlayers: number;
    questionsAnswered: number;
    totalAnswers: number;
    correctAnswers: number;
    fastestAnswer: number | null;
    fastestPlayer: string | null;
    mostActivePlayer: string | null;
    sessionDuration: number;
  };
  sessionId: number | null;
}

type TabType = "control" | "leaderboard" | "stats" | "tiktok" | "simulate";

export default function AdminPage() {
  const [game, setGame] = useState<GameData | null>(null);
  const [tab, setTab] = useState<TabType>("control");
  const [tiktokUsername, setTiktokUsername] = useState("");
  const [tiktokConnected, setTiktokConnected] = useState(false);
  const [questionCount, setQuestionCount] = useState(20);
  const [difficulty, setDifficulty] = useState("mixed");
  const [simUsername, setSimUsername] = useState("");
  const [simMessage, setSimMessage] = useState("");
  const [events, setEvents] = useState<{ type: string; data: string; time: string }[]>([]);
  const [addPointsUser, setAddPointsUser] = useState("");
  const [addPointsAmount, setAddPointsAmount] = useState(10);
  const pollRef = useRef<ReturnType<typeof setInterval>>(null);

  const fetchGame = useCallback(async () => {
    try {
      const res = await fetch("/api/game");
      const data = await res.json();
      setGame(data);
    } catch {
      /* ignore */
    }
  }, []);

  useEffect(() => {
    fetchGame();
    pollRef.current = setInterval(fetchGame, 500);
    return () => {
      if (pollRef.current) clearInterval(pollRef.current);
    };
  }, [fetchGame]);

  const gameAction = async (action: string, extra: Record<string, unknown> = {}) => {
    try {
      const res = await fetch("/api/game", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ action, ...extra }),
      });
      const data = await res.json();
      addEvent(action, JSON.stringify(data));
      fetchGame();
    } catch {
      /* ignore */
    }
  };

  const simulateAnswer = async () => {
    if (!simUsername || !simMessage) return;
    try {
      const res = await fetch("/api/game/answer", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          username: simUsername.toLowerCase().replace(/\s/g, "_"),
          displayName: simUsername,
          message: simMessage,
        }),
      });
      const data = await res.json();
      addEvent("answer", `${simUsername}: "${simMessage}" → ${data.correct ? "✅ CORRECT" : "❌ Wrong"}`);
      setSimMessage("");
      fetchGame();
    } catch {
      /* ignore */
    }
  };

  const connectTikTok = async () => {
    try {
      const res = await fetch("/api/tiktok", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ action: "connect", username: tiktokUsername }),
      });
      const data = await res.json();
      setTiktokConnected(data.connected);
      addEvent("tiktok", `Connected to @${tiktokUsername}`);
    } catch {
      /* ignore */
    }
  };

  const disconnectTikTok = async () => {
    try {
      await fetch("/api/tiktok", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ action: "disconnect" }),
      });
      setTiktokConnected(false);
      addEvent("tiktok", "Disconnected");
    } catch {
      /* ignore */
    }
  };

  const addEvent = (type: string, data: string) => {
    setEvents((prev) => [
      { type, data, time: new Date().toLocaleTimeString() },
      ...prev.slice(0, 49),
    ]);
  };

  const exportResults = async (format: string) => {
    const res = await fetch(`/api/game/export?format=${format}`);
    if (format === "csv") {
      const blob = await res.blob();
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `anime-wiz-results.csv`;
      a.click();
    } else {
      const data = await res.json();
      const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `anime-wiz-results.json`;
      a.click();
    }
  };

  const formatDuration = (ms: number) => {
    const s = Math.floor(ms / 1000);
    const m = Math.floor(s / 60);
    const h = Math.floor(m / 60);
    return `${h}h ${m % 60}m ${s % 60}s`;
  };

  const diffBadge = (d: string) => {
    const colors: Record<string, string> = {
      easy: "bg-cyan-500/20 text-cyan-300 border-cyan-500/40",
      medium: "bg-yellow-500/20 text-yellow-300 border-yellow-500/40",
      hard: "bg-orange-500/20 text-orange-300 border-orange-500/40",
      legendary: "bg-red-500/20 text-red-300 border-red-500/40",
    };
    return colors[d] || "bg-gray-500/20 text-gray-300 border-gray-500/40";
  };

  return (
    <div className="anime-bg min-h-screen">
      <div className="anime-bg" />

      {/* Header */}
      <header className="glass-card neon-border-pink mx-4 mt-4 p-4 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <span className="text-3xl">🎮</span>
          <div>
            <h1
              className="text-2xl font-bold neon-text"
              style={{ fontFamily: "Orbitron, sans-serif" }}
            >
              ANIME WIZ LIVE ARENA
            </h1>
            <p className="text-sm text-purple-300 opacity-70">Admin Control Panel</p>
          </div>
        </div>
        <div className="flex items-center gap-4 text-sm">
          <div className="flex items-center gap-2">
            <span
              className={`w-2 h-2 rounded-full ${
                game?.status === "question"
                  ? "bg-green-400 animate-pulse"
                  : game?.status === "active" || game?.status === "revealing"
                  ? "bg-yellow-400"
                  : "bg-gray-500"
              }`}
            />
            <span className="text-gray-300 uppercase" style={{ fontFamily: "Orbitron" }}>
              {game?.status || "offline"}
            </span>
          </div>
          <div className="text-purple-300">
            👥 {game?.totalPlayers || 0} players
          </div>
          {game?.sessionId && (
            <div className="text-gray-400">Session #{game.sessionId}</div>
          )}
        </div>
      </header>

      {/* Tabs */}
      <nav className="flex gap-2 mx-4 mt-4 overflow-x-auto">
        {(
          [
            ["control", "🎮 Control"],
            ["leaderboard", "🏆 Leaderboard"],
            ["stats", "📊 Stats"],
            ["tiktok", "📱 TikTok"],
            ["simulate", "🧪 Simulate"],
          ] as [TabType, string][]
        ).map(([key, label]) => (
          <button
            key={key}
            onClick={() => setTab(key)}
            className={`btn-neon text-xs whitespace-nowrap ${
              tab === key ? "btn-neon-purple" : "bg-slate-800/50 text-gray-400"
            }`}
          >
            {label}
          </button>
        ))}
        <a
          href="/overlay"
          target="_blank"
          className="btn-neon btn-neon-pink text-xs ml-auto whitespace-nowrap"
        >
          🖥️ Open Overlay
        </a>
      </nav>

      {/* Content */}
      <main className="mx-4 mt-4 pb-8">
        {/* ─── Control Tab ─── */}
        {tab === "control" && (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
            {/* Game Controls */}
            <div className="glass-card neon-border p-5 lg:col-span-2 animate-fade-in">
              <h2
                className="text-lg font-bold text-purple-300 mb-4"
                style={{ fontFamily: "Orbitron" }}
              >
                GAME CONTROLS
              </h2>

              {game?.status === "waiting" && (
                <div className="space-y-4">
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="text-sm text-gray-400 block mb-1">Questions</label>
                      <input
                        type="number"
                        value={questionCount}
                        onChange={(e) => setQuestionCount(Number(e.target.value))}
                        min={5}
                        max={100}
                        className="w-full"
                      />
                    </div>
                    <div>
                      <label className="text-sm text-gray-400 block mb-1">Difficulty</label>
                      <select
                        value={difficulty}
                        onChange={(e) => setDifficulty(e.target.value)}
                        className="w-full"
                      >
                        <option value="mixed">Mixed</option>
                        <option value="easy">Easy</option>
                        <option value="medium">Medium</option>
                        <option value="hard">Hard</option>
                        <option value="legendary">Legendary</option>
                      </select>
                    </div>
                  </div>
                  <button
                    onClick={() =>
                      gameAction("start", { questionCount, difficulty })
                    }
                    className="btn-neon btn-neon-green w-full text-lg py-3"
                  >
                    🚀 START GAME
                  </button>
                </div>
              )}

              {(game?.status === "active" || game?.status === "revealing") && (
                <div className="space-y-3">
                  <button
                    onClick={() => gameAction("next_question")}
                    className="btn-neon btn-neon-blue w-full text-lg py-3"
                  >
                    ➡️ NEXT QUESTION
                  </button>
                  <div className="grid grid-cols-3 gap-2">
                    <button
                      onClick={() => gameAction("pause")}
                      className="btn-neon btn-neon-gold"
                    >
                      ⏸️ Pause
                    </button>
                    <button
                      onClick={() => gameAction("skip")}
                      className="btn-neon bg-slate-700 text-gray-300"
                    >
                      ⏭️ Skip
                    </button>
                    <button
                      onClick={() => gameAction("end")}
                      className="btn-neon btn-neon-red"
                    >
                      🏁 End Game
                    </button>
                  </div>
                </div>
              )}

              {game?.status === "question" && (
                <div className="space-y-3">
                  <div className="grid grid-cols-3 gap-2">
                    <button
                      onClick={() => gameAction("pause")}
                      className="btn-neon btn-neon-gold"
                    >
                      ⏸️ Pause
                    </button>
                    <button
                      onClick={() => gameAction("skip")}
                      className="btn-neon bg-slate-700 text-gray-300"
                    >
                      ⏭️ Skip
                    </button>
                    <button
                      onClick={() => gameAction("end")}
                      className="btn-neon btn-neon-red"
                    >
                      🏁 End Game
                    </button>
                  </div>
                </div>
              )}

              {game?.status === "paused" && (
                <div className="space-y-3">
                  <button
                    onClick={() => gameAction("resume")}
                    className="btn-neon btn-neon-green w-full text-lg py-3"
                  >
                    ▶️ RESUME GAME
                  </button>
                </div>
              )}

              {game?.status === "completed" && (
                <div className="space-y-3">
                  <div className="text-center text-2xl font-bold text-yellow-300 neon-text-gold mb-4">
                    🏆 GAME COMPLETE! 🏆
                  </div>
                  <div className="grid grid-cols-2 gap-2">
                    <button
                      onClick={() => exportResults("json")}
                      className="btn-neon btn-neon-blue"
                    >
                      📥 Export JSON
                    </button>
                    <button
                      onClick={() => exportResults("csv")}
                      className="btn-neon btn-neon-green"
                    >
                      📥 Export CSV
                    </button>
                  </div>
                  <button
                    onClick={() => gameAction("reset")}
                    className="btn-neon btn-neon-purple w-full"
                  >
                    🔄 New Game
                  </button>
                </div>
              )}

              {/* Moderator: Add Points / Ban */}
              {game && game.status !== "waiting" && (
                <div className="mt-6 pt-4 border-t border-purple-500/20">
                  <h3 className="text-sm font-bold text-gray-400 mb-2">MOD TOOLS</h3>
                  <div className="flex gap-2 mb-2">
                    <input
                      type="text"
                      placeholder="Username"
                      value={addPointsUser}
                      onChange={(e) => setAddPointsUser(e.target.value)}
                      className="flex-1 text-sm"
                    />
                    <input
                      type="number"
                      value={addPointsAmount}
                      onChange={(e) => setAddPointsAmount(Number(e.target.value))}
                      className="w-20 text-sm"
                    />
                    <button
                      onClick={() => {
                        gameAction("add_points", {
                          username: addPointsUser,
                          points: addPointsAmount,
                        });
                        setAddPointsUser("");
                      }}
                      className="btn-neon btn-neon-gold text-xs"
                    >
                      +Points
                    </button>
                    <button
                      onClick={() => {
                        gameAction("ban", { username: addPointsUser });
                        setAddPointsUser("");
                      }}
                      className="btn-neon btn-neon-red text-xs"
                    >
                      Ban
                    </button>
                  </div>
                </div>
              )}
            </div>

            {/* Current Question */}
            <div className="glass-card neon-border p-5 animate-fade-in">
              <h2
                className="text-lg font-bold text-purple-300 mb-4"
                style={{ fontFamily: "Orbitron" }}
              >
                CURRENT QUESTION
              </h2>
              {game?.currentQuestion ? (
                <div className="space-y-3">
                  <div className="flex items-center gap-2">
                    <span
                      className={`q-type-badge border ${diffBadge(
                        game.currentQuestion.difficulty
                      )}`}
                    >
                      {game.currentQuestion.difficulty}
                    </span>
                    <span className="text-xs text-gray-500">
                      {game.currentQuestion.type.replace(/_/g, " ")}
                    </span>
                  </div>
                  {game.bossRound && (
                    <div className="text-red-400 font-bold text-sm animate-pulse">
                      ⚔️ BOSS ROUND ⚔️
                    </div>
                  )}
                  <p className="text-white text-base font-medium">
                    {game.currentQuestion.question}
                  </p>
                  {game.currentQuestion.options.length > 0 && (
                    <div className="space-y-1">
                      {game.currentQuestion.options.map((opt, i) => (
                        <div
                          key={i}
                          className="text-sm text-gray-300 bg-slate-800/50 px-3 py-1.5 rounded"
                        >
                          {opt}
                        </div>
                      ))}
                    </div>
                  )}

                  {/* Timer */}
                  <div className="mt-3">
                    <div className="flex justify-between text-xs mb-1">
                      <span className="text-gray-400">Time</span>
                      <span
                        className={`font-bold ${
                          game.timeRemaining <= 5
                            ? "text-red-400"
                            : game.timeRemaining <= 10
                            ? "text-yellow-400"
                            : "text-cyan-400"
                        }`}
                      >
                        {game.timeRemaining}s
                      </span>
                    </div>
                    <div className="w-full bg-slate-800 rounded-full h-1.5">
                      <div
                        className={`timer-bar ${
                          game.timeRemaining <= 5
                            ? "critical"
                            : game.timeRemaining <= 10
                            ? "warning"
                            : ""
                        }`}
                        style={{
                          width: `${
                            (game.timeRemaining /
                              game.currentQuestion.timeLimit) *
                            100
                          }%`,
                        }}
                      />
                    </div>
                  </div>

                  {/* Answer */}
                  {game.correctAnswer && (
                    <div className="mt-3 p-3 bg-green-500/10 border border-green-500/30 rounded-lg">
                      <p className="text-green-400 font-bold text-sm">
                        ✅ Answer: {game.correctAnswer}
                      </p>
                      {game.winnerDisplayName && (
                        <p className="text-yellow-300 text-sm mt-1">
                          🏆 Winner: {game.winnerDisplayName}
                        </p>
                      )}
                    </div>
                  )}

                  <div className="text-xs text-gray-500 mt-2">
                    Q{game.questionsAsked}/{game.totalQuestions}
                  </div>
                </div>
              ) : (
                <div className="text-gray-500 text-center py-8">
                  {game?.status === "waiting"
                    ? "Start a game to see questions"
                    : "Click 'Next Question' to begin"}
                </div>
              )}
            </div>

            {/* Event Log */}
            <div className="glass-card neon-border p-5 lg:col-span-3 animate-fade-in">
              <h2
                className="text-lg font-bold text-purple-300 mb-3"
                style={{ fontFamily: "Orbitron" }}
              >
                EVENT LOG
              </h2>
              <div className="max-h-48 overflow-y-auto space-y-1">
                {events.length === 0 ? (
                  <p className="text-gray-600 text-sm">No events yet</p>
                ) : (
                  events.map((e, i) => (
                    <div
                      key={i}
                      className="text-xs flex gap-2 py-1 border-b border-slate-800/50"
                    >
                      <span className="text-gray-600 w-16 shrink-0">
                        {e.time}
                      </span>
                      <span className="text-purple-400 w-20 shrink-0 uppercase font-bold">
                        {e.type}
                      </span>
                      <span className="text-gray-300 truncate">{e.data}</span>
                    </div>
                  ))
                )}
              </div>
            </div>
          </div>
        )}

        {/* ─── Leaderboard Tab ─── */}
        {tab === "leaderboard" && (
          <div className="glass-card neon-border-gold p-5 animate-fade-in">
            <h2
              className="text-xl font-bold text-yellow-300 neon-text-gold mb-4"
              style={{ fontFamily: "Orbitron" }}
            >
              🏆 LIVE LEADERBOARD
            </h2>
            {game?.leaderboard && game.leaderboard.length > 0 ? (
              <div className="space-y-2">
                {game.leaderboard.map((p) => (
                  <div
                    key={p.username}
                    className="lb-entry flex items-center gap-3 bg-slate-800/40 p-3 rounded-xl"
                  >
                    <div
                      className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-bold ${
                        p.rank === 1
                          ? "rank-1"
                          : p.rank === 2
                          ? "rank-2"
                          : p.rank === 3
                          ? "rank-3"
                          : "bg-slate-700 text-gray-400"
                      }`}
                    >
                      {p.rank}
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2">
                        <span className="font-bold text-white truncate">
                          {p.displayName}
                        </span>
                        <span className="text-xs text-purple-400">
                          {p.title}
                        </span>
                      </div>
                      <div className="text-xs text-gray-500">
                        @{p.username}
                        {p.team && (
                          <span className="ml-2 text-cyan-400">{p.team}</span>
                        )}
                      </div>
                    </div>
                    <div className="text-right">
                      <div className="font-bold text-yellow-300 text-lg">
                        {p.points}
                      </div>
                      {p.streak > 0 && (
                        <div className="text-xs text-orange-400">
                          🔥 {p.streak} streak
                        </div>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <p className="text-gray-500 text-center py-8">
                No players yet. Start a game!
              </p>
            )}
          </div>
        )}

        {/* ─── Stats Tab ─── */}
        {tab === "stats" && game && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 animate-fade-in">
            {[
              {
                label: "Total Players",
                value: game.stats.totalPlayers,
                icon: "👥",
                color: "text-cyan-400",
              },
              {
                label: "Questions Asked",
                value: game.stats.questionsAnswered,
                icon: "❓",
                color: "text-purple-400",
              },
              {
                label: "Total Answers",
                value: game.stats.totalAnswers,
                icon: "💬",
                color: "text-pink-400",
              },
              {
                label: "Correct Answers",
                value: game.stats.correctAnswers,
                icon: "✅",
                color: "text-green-400",
              },
              {
                label: "Accuracy",
                value:
                  game.stats.totalAnswers > 0
                    ? `${Math.round(
                        (game.stats.correctAnswers / game.stats.totalAnswers) *
                          100
                      )}%`
                    : "N/A",
                icon: "🎯",
                color: "text-yellow-400",
              },
              {
                label: "Fastest Answer",
                value: game.stats.fastestAnswer
                  ? `${game.stats.fastestAnswer.toFixed(1)}s`
                  : "N/A",
                icon: "⚡",
                color: "text-orange-400",
              },
              {
                label: "Fastest Player",
                value: game.stats.fastestPlayer || "N/A",
                icon: "🏃",
                color: "text-cyan-300",
              },
              {
                label: "Session Duration",
                value: formatDuration(game.stats.sessionDuration),
                icon: "⏱️",
                color: "text-gray-300",
              },
            ].map((stat, i) => (
              <div key={i} className="glass-card neon-border p-4">
                <div className="text-2xl mb-2">{stat.icon}</div>
                <div className="text-xs text-gray-500 uppercase">
                  {stat.label}
                </div>
                <div className={`text-xl font-bold ${stat.color}`}>
                  {stat.value}
                </div>
              </div>
            ))}
          </div>
        )}

        {/* ─── TikTok Tab ─── */}
        {tab === "tiktok" && (
          <div className="glass-card neon-border-pink p-5 max-w-lg animate-fade-in">
            <h2
              className="text-lg font-bold text-pink-300 mb-4"
              style={{ fontFamily: "Orbitron" }}
            >
              📱 TIKTOK LIVE CONNECTION
            </h2>
            {!tiktokConnected ? (
              <div className="space-y-4">
                <div>
                  <label className="text-sm text-gray-400 block mb-1">
                    TikTok Username
                  </label>
                  <input
                    type="text"
                    placeholder="@your_username"
                    value={tiktokUsername}
                    onChange={(e) => setTiktokUsername(e.target.value)}
                    className="w-full"
                  />
                </div>
                <button
                  onClick={connectTikTok}
                  className="btn-neon btn-neon-pink w-full"
                >
                  🔗 Connect to TikTok Live
                </button>
                <p className="text-xs text-gray-500">
                  Note: Requires an active TikTok Live stream. In demo mode, the connection is simulated. Use the Simulate tab to test answers.
                </p>
              </div>
            ) : (
              <div className="space-y-4">
                <div className="flex items-center gap-3 bg-green-500/10 border border-green-500/30 rounded-lg p-3">
                  <span className="w-3 h-3 rounded-full bg-green-400 animate-pulse" />
                  <div>
                    <p className="text-green-300 font-bold">Connected</p>
                    <p className="text-xs text-gray-400">
                      @{tiktokUsername}
                    </p>
                  </div>
                </div>
                <button
                  onClick={disconnectTikTok}
                  className="btn-neon btn-neon-red w-full"
                >
                  Disconnect
                </button>
              </div>
            )}
          </div>
        )}

        {/* ─── Simulate Tab ─── */}
        {tab === "simulate" && (
          <div className="glass-card neon-border-blue p-5 max-w-lg animate-fade-in">
            <h2
              className="text-lg font-bold text-cyan-300 mb-4"
              style={{ fontFamily: "Orbitron" }}
            >
              🧪 SIMULATE CHAT
            </h2>
            <p className="text-xs text-gray-500 mb-4">
              Test the game by simulating TikTok chat messages. This is useful for
              localhost testing without a live TikTok stream.
            </p>
            <div className="space-y-3">
              <div>
                <label className="text-sm text-gray-400 block mb-1">
                  Username
                </label>
                <input
                  type="text"
                  placeholder="test_user"
                  value={simUsername}
                  onChange={(e) => setSimUsername(e.target.value)}
                  className="w-full"
                />
              </div>
              <div>
                <label className="text-sm text-gray-400 block mb-1">
                  Answer / Message
                </label>
                <input
                  type="text"
                  placeholder="Type answer..."
                  value={simMessage}
                  onChange={(e) => setSimMessage(e.target.value)}
                  className="w-full"
                  onKeyDown={(e) => e.key === "Enter" && simulateAnswer()}
                />
              </div>
              <button
                onClick={simulateAnswer}
                className="btn-neon btn-neon-blue w-full"
              >
                📨 Send Answer
              </button>
              <div className="mt-3 pt-3 border-t border-slate-700">
                <p className="text-xs text-gray-500 mb-2">Quick Actions:</p>
                <div className="flex gap-2 flex-wrap">
                  {["!double", "!shield", "!steal"].map((cmd) => (
                    <button
                      key={cmd}
                      onClick={() => {
                        setSimMessage(cmd);
                        setTimeout(simulateAnswer, 100);
                      }}
                      className="btn-neon bg-slate-700 text-gray-300 text-xs"
                    >
                      {cmd}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
}
